    "pdg_02323": {
      "pl": "<div class=\"fixture devMode370\"><div class=\"row spread\"><div><b>TRYB DEWELOPERSKI</b><div class=\"small\">Możesz przejść do dowolnego klubu poniżej. Transfer zawsze dotyczy <b>PIERWSZEJ drużyny</b>, także po kliknięciu zespołu U-19, II lub III.</div></div><span class=\"tag\">DEV</span></div></div>",
      "en": "<div class=\"fixture devMode370\"><div class=\"row spread\"><div><b>DEVELOPER MODE</b><div class=\"small\">You can move to any club below. The transfer always applies to the <b>FIRST TEAM</b>, even after clicking a U-19, reserve or third team.</div></div><span class=\"tag\">DEV</span></div></div>"
    },
